/**
 * Teams mode defaults and normalization (settings.teams object).
 * Open-queue code must not import side effects from here into hot paths — only normalize for persistence/UI.
 */

export const UNASSIGNED_TEAM_ID = "__unassigned__";

export const TEAM_COLOR_PALETTE = [
  { key: "blue", hex: "#2563EB", label: "Blue" },
  { key: "green", hex: "#16A34A", label: "Green" },
  { key: "red", hex: "#DC2626", label: "Red" },
  { key: "orange", hex: "#EA580C", label: "Orange" },
  { key: "purple", hex: "#9333EA", label: "Purple" },
  { key: "pink", hex: "#DB2777", label: "Pink" },
  { key: "yellow", hex: "#CA8A04", label: "Yellow" },
  { key: "teal", hex: "#0D9488", label: "Teal" },
];

export const DEFAULT_TEAMS_SETTINGS = {
  levelMode: "balanced",
  pairRotationStrength: "normal",
  enforceSessionRepeatThreePlayer: true,
  enforceSessionRepeatFourExact: true,
  showTopTeamsOnDisplay: true,
  topTeamsRunnerUpCount: 2,
  topTeamsRankingMode: "winsFirst",
  showVersusDisclaimer: true,
  unassignedLabel: "Unassigned",
  unassignedColorKey: "neutral",
};

export function normalizeTeamsSettings(raw = {}) {
  const t = typeof raw === "object" && raw ? raw : {};
  const runner = Number(t.topTeamsRunnerUpCount);
  return {
    ...DEFAULT_TEAMS_SETTINGS,
    ...t,
    levelMode: t.levelMode === "strict" ? "strict" : "balanced",
    pairRotationStrength: t.pairRotationStrength === "strong" ? "strong" : "normal",
    enforceSessionRepeatThreePlayer:
      typeof t.enforceSessionRepeatThreePlayer === "boolean"
        ? t.enforceSessionRepeatThreePlayer
        : DEFAULT_TEAMS_SETTINGS.enforceSessionRepeatThreePlayer,
    enforceSessionRepeatFourExact:
      typeof t.enforceSessionRepeatFourExact === "boolean"
        ? t.enforceSessionRepeatFourExact
        : DEFAULT_TEAMS_SETTINGS.enforceSessionRepeatFourExact,
    showTopTeamsOnDisplay:
      typeof t.showTopTeamsOnDisplay === "boolean"
        ? t.showTopTeamsOnDisplay
        : DEFAULT_TEAMS_SETTINGS.showTopTeamsOnDisplay,
    topTeamsRunnerUpCount: [0, 1, 2].includes(runner) ? runner : DEFAULT_TEAMS_SETTINGS.topTeamsRunnerUpCount,
    topTeamsRankingMode:
      t.topTeamsRankingMode === "winRateFirst" ? "winRateFirst" : "winsFirst",
    showVersusDisclaimer:
      typeof t.showVersusDisclaimer === "boolean"
        ? t.showVersusDisclaimer
        : DEFAULT_TEAMS_SETTINGS.showVersusDisclaimer,
    unassignedLabel:
      typeof t.unassignedLabel === "string" && t.unassignedLabel.trim()
        ? t.unassignedLabel.trim()
        : DEFAULT_TEAMS_SETTINGS.unassignedLabel,
    unassignedColorKey:
      typeof t.unassignedColorKey === "string" ? t.unassignedColorKey : DEFAULT_TEAMS_SETTINGS.unassignedColorKey,
  };
}

export function normalizeTeamRecord(raw) {
  if (!raw || raw.id == null) return null;
  const id = String(raw.id);
  const name = typeof raw.name === "string" && raw.name.trim() ? raw.name.trim() : "Team";
  let letter =
    typeof raw.letter === "string" && raw.letter.trim()
      ? raw.letter.trim().charAt(0).toUpperCase()
      : name.charAt(0).toUpperCase() || "?";
  if (!/[A-Z]/.test(letter)) letter = "?";
  return {
    id,
    name,
    color: typeof raw.color === "string" ? raw.color : "#3B82F6",
    letter,
    createdAt: typeof raw.createdAt === "number" ? raw.createdAt : Date.now(),
    isActive: raw.isActive !== false,
  };
}
