/** Normalize player/court ids for Set/includes comparisons (persisted state vs broadcast). */
export const playerIdKey = (id) => String(id);

export function findCourtById(courts, courtId) {
  if (courtId == null || !Array.isArray(courts)) return null;
  const key = playerIdKey(courtId);
  return courts.find((c) => c && playerIdKey(c.id) === key) || null;
}

export function listHasPlayerId(playerIds, playerId) {
  if (playerId == null) return false;
  const key = playerIdKey(playerId);
  return (playerIds || []).some((pid) => playerIdKey(pid) === key);
}

export function courtHasPlayerId(court, playerId) {
  if (!court) return false;
  return listHasPlayerId(court.players, playerId);
}

/** Players currently assigned to a court, in court.players order. */
export function getPlayersOnCourt(court, players = []) {
  if (!court || !Array.isArray(players)) return [];
  const byId = new Map(players.map((p) => [playerIdKey(p.id), p]));
  return (court.players || [])
    .map((pid) => byId.get(playerIdKey(pid)))
    .filter(Boolean);
}
