    const currentSlots = booking.slotIds.map(id => slotsV2[id]).filter(Boolean);

    // 2. Merge
    const mergedSlots = currentSlots.map(existing => {
      const modified = modifiedSlotsList.find(m => m.slotId === existing.slotId);
      return modified || existing;
    });

    // 3. Update 
    return updateBookingV2(bookingId, { slots: mergedSlots });
