import React from 'react';

function clampNumber(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

// Renders a circular avatar with a colored frame (ring) around the image.
// Props:
// - src: image URL
// - alt: alt text
// - frameColor: ring color (pass your level color here)
// - size: outer diameter in px (default 88)
// - ring: ring thickness in px (default 4)
// - gap: inner spacing between ring and image in px (default 2)
// - background: background color behind the image (default '#fff')
// - style: extra styles for the outer wrapper
// - imgStyle: extra styles for the image
export default function LevelAvatar({
  src,
  alt = '',
  frameColor = '#888',
  size = 88,
  ring = 4,
  gap = 2,
  background = '#fff',
  style,
  imgStyle,
  fallback, // optional text fallback when no image URL
  fallbackScale = 0.585, // proportion of inner circle for initial (~+30% vs prior 0.45)
}) {
  const safeSize = clampNumber(Number(size) || 88, 28, 256);
  const safeRing = clampNumber(Number(ring) || 4, 0, 16);
  const safeGap = clampNumber(Number(gap) || 2, 0, 12);

  const innerBox = safeSize - safeRing * 2;
  const imageBox = innerBox - safeGap * 2;
  const hasSrc = !!src;
  const fallbackText = (fallback || alt || '').trim().charAt(0).toUpperCase();

  return (
    <div
      style={{
        width: safeSize,
        height: safeSize,
        borderRadius: '50%',
        backgroundColor: frameColor,
        padding: safeRing,
        boxSizing: 'border-box',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        ...style,
      }}
      aria-label={alt}
      role="img"
    >
      <div
        style={{
          width: innerBox,
          height: innerBox,
          borderRadius: '50%',
          backgroundColor: frameColor,
          padding: safeGap,
          boxSizing: 'border-box',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {hasSrc ? (
          <img
            src={src}
            alt={alt}
            style={{
              width: imageBox,
              height: imageBox,
              borderRadius: '50%',
              objectFit: 'cover',
              display: 'block',
              backgroundColor: background,
              ...imgStyle,
            }}
          />
        ) : (
          <div
            aria-hidden="true"
            style={{
              width: imageBox,
              height: imageBox,
              borderRadius: '50%',
              backgroundColor: background,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 700,
              color: '#111827',
              fontSize: Math.max(12, Math.floor(imageBox * fallbackScale)),
              userSelect: 'none',
            }}
          >
            {fallbackText || '•'}
          </div>
        )}
      </div>
    </div>
  );
}
