import config from "../../config";

const dropUndefined = (obj) =>
  Object.fromEntries(Object.entries(obj).filter(([, value]) => value !== undefined));

export const lockedRentalHours = () => ({
  lowStartHour: Number(config.pricing?.rentalRates?.lowStartHour) || 8,
  midStartHour: Number(config.pricing?.rentalRates?.midStartHour) || 12,
  highStartHour: Number(config.pricing?.rentalRates?.highStartHour) || 17,
  closeHour: Number(config.pricing?.rentalRates?.closeHour) || 22,
});

export const withLockedRentalHours = (rates = {}) => ({
  ...rates,
  ...lockedRentalHours(),
});

/** Neon `calendar_settings` → flat local settings keys. Missing keys are dropped
 *  so a partial record cannot blank out a value the app already has. */
export const calendarSettingsToLocal = (cs = {}) =>
  dropUndefined({
    defaultQueueCourts: cs.ops?.defaultQueueCourts,
    defaultOpFee: cs.pricing?.openPlayRate,
    memberDiscount: cs.pricing?.memberDiscount,
    pickleCamFee: cs.pricing?.pickleCamFee,
    ballFee: cs.pricing?.ballFee,
    defaultRentalRate: cs.pricing?.defaultRentalRate,
    rentalPromo: cs.pricing?.rentalPromo,
    rentalRates: cs.pricing?.rentalRates
      ? withLockedRentalHours(cs.pricing.rentalRates)
      : undefined,
    calendarOpenHour: cs.calendar?.openHour,
    calendarCloseHour: cs.calendar?.closeHour,
    defaultCalendarCourts: cs.ops?.defaultCalendarCourts,
    gcashName: cs.pricing?.invoice?.gcashName,
    gcashNumber: cs.pricing?.invoice?.gcashNumber,
    pickleCamPricingMode: cs.pricing?.pickleCamPricingMode,
  });

/** Flat local settings → Neon `calendar_settings`. The admin block is never sent. */
export const localToCalendarSettings = (local, existing = {}) => {
  const { admin: _admin, ...existingSafe } = existing || {};
  return {
    ...existingSafe,
    version: 1,
    timezone: existingSafe.timezone || "Asia/Manila",
    calendar: {
      ...(existingSafe.calendar || {}),
      openHour: local.calendarOpenHour,
      closeHour: local.calendarCloseHour,
      courts: existingSafe.calendar?.courts || config.calendar?.courts || [],
      defaultView: existingSafe.calendar?.defaultView || "timeGridDay",
    },
    pricing: {
      ...(existingSafe.pricing || {}),
      openPlayRate: local.defaultOpFee,
      memberDiscount: local.memberDiscount,
      pickleCamFee: local.pickleCamFee,
      ballFee: local.ballFee,
      defaultRentalRate: local.defaultRentalRate,
      rentalPromo: local.rentalPromo ?? existingSafe.pricing?.rentalPromo,
      rentalRates: withLockedRentalHours(local.rentalRates || {}),
      pickleCamPricingMode:
        local.pickleCamPricingMode || existingSafe.pricing?.pickleCamPricingMode || "hourly",
      invoice: {
        ...(existingSafe.pricing?.invoice || config.pricing?.invoice || {}),
        ...(local.gcashName !== undefined ? { gcashName: local.gcashName } : {}),
        ...(local.gcashNumber !== undefined ? { gcashNumber: local.gcashNumber } : {}),
      },
    },
    ops: {
      ...(existingSafe.ops || {}),
      defaultQueueCourts: local.defaultQueueCourts,
      defaultCalendarCourts: local.defaultCalendarCourts,
    },
    publicBooking: existingSafe.publicBooking,
  };
};

/** Overlay Neon-mapped values onto in-memory settings. Online fees win. */
export const mergeOnlineSettings = (prev = {}, mapped = {}) => {
  const next = { ...prev, ...mapped };
  if (mapped.rentalRates) {
    next.rentalRates = withLockedRentalHours({
      ...prev.rentalRates,
      ...mapped.rentalRates,
      weekday: {
        ...(prev.rentalRates?.weekday || {}),
        ...(mapped.rentalRates.weekday || {}),
      },
      weekend: {
        ...(prev.rentalRates?.weekend || {}),
        ...(mapped.rentalRates.weekend || {}),
      },
    });
  }
  return next;
};

/** Live Neon GCash wins over hydrated settings; settings win over client config. */
export const resolveInvoiceGcash = (settings = {}, live = null, fallback = {}) => {
  const fromSettings = {
    gcashName: String(settings.gcashName || fallback.gcashName || "").trim(),
    gcashNumber: String(settings.gcashNumber || fallback.gcashNumber || "").trim(),
  };
  if (!live) return fromSettings;
  return {
    gcashName: String(live.gcashName ?? fromSettings.gcashName).trim(),
    gcashNumber: String(live.gcashNumber ?? fromSettings.gcashNumber).trim(),
  };
};
