const commitAllFields = (baseSettings, draft, fields) => {
  let next = { ...baseSettings };
  fields.forEach((field) => {
    const raw = draft[field.key];
    try {
      let parsed;
      if (field.type === "number") {
        if (raw === "" || raw === null || raw === undefined) return;
        parsed = Number(raw);
        if (!Number.isFinite(parsed)) return;
        if (typeof field.min === "number" && parsed < field.min) parsed = field.min;
        if (typeof field.max === "number" && parsed > field.max) parsed = field.max;
      } else {
        parsed = raw ?? "";
      }
      if (typeof field.applyValue === "function") {
        next = field.applyValue(next, parsed);
      } else {
        next = { ...next, [field.key]: parsed };
      }
    } catch {
      /* skip invalid field */
    }
  });
  return next;
};

/** Prefer the values currently in the inputs over React state, so Apply and Save
 *  still picks up the field the admin has focused (or last typed). */
const collectLiveDraft = (form, fields, fallback = {}) => {
  const draft = { ...fallback };
  if (!form) return draft;
  fields.forEach((field) => {
    const el = form.elements?.namedItem(field.key);
    if (el && typeof el.value === "string") draft[field.key] = el.value;
  });
  return draft;
};

function ProtectedSettingsBlock({ settings, setSettings, fields, layout = "stack", autoSave = true, draftRef }) {
  const getFieldValue = React.useCallback(
    (field) => (typeof field.getValue === "function" ? field.getValue(settings) : settings[field.key]),
    [settings]
  );

  const buildDraft = React.useCallback(() => {
    const initial = {};
    fields.forEach((f) => {
      const value = getFieldValue(f);
      initial[f.key] = value === null || value === undefined ? "" : String(value);
    });
    return initial;
  }, [fields, getFieldValue]);

  const [draft, setDraft] = React.useState(buildDraft);
  const [fieldErrors, setFieldErrors] = React.useState({});

  React.useEffect(() => {
    setDraft(buildDraft());
    setFieldErrors({});
  }, [buildDraft]);

  React.useEffect(() => {
    if (draftRef) draftRef.current = draft;
  }, [draft, draftRef]);

  const revertField = React.useCallback(
    (key) => {
      const field = fields.find((f) => f.key === key);
      const value = field ? getFieldValue(field) : settings[key];
      setDraft((prev) => ({
        ...prev,
        [key]: value === null || value === undefined ? "" : String(value),
      }));
    },
    [fields, getFieldValue, settings]
  );

  const parseFieldValue = React.useCallback((field, rawValue) => {
    if (field.type === "number") {
      if (rawValue === "" || rawValue === null || rawValue === undefined) {
        throw new Error("Please enter a value.");
      }
      let numeric = Number(rawValue);
      if (!Number.isFinite(numeric)) {
        throw new Error("Please enter a valid number.");
      }
      if (typeof field.min === "number" && numeric < field.min) {
        numeric = field.min;
      }
      if (typeof field.max === "number" && numeric > field.max) {
        numeric = field.max;
      }
      return numeric;
    }
    return rawValue ?? "";
  }, []);

  const commitField = React.useCallback(
    async (field) => {
      const { key } = field;
      try {
        const parsedValue = parseFieldValue(field, draft[key]);
        if (typeof field.onCommit === "function") {
          await field.onCommit(parsedValue, { previousValue: getFieldValue(field) });
        }
        if (typeof field.applyValue === "function") {
          setSettings((prev) => field.applyValue(prev, parsedValue));
        } else {
          setSettings((prev) => ({ ...prev, [key]: parsedValue }));
        }
        setFieldErrors((prev) => ({ ...prev, [key]: null }));
      } catch (error) {
        setFieldErrors((prev) => ({
          ...prev,
          [key]: error?.message || "Unable to save this value. Please try again.",
        }));
        revertField(key);
      }
    },
    [draft, getFieldValue, parseFieldValue, revertField, setSettings]
  );

  const containerClass =
    layout === "grid"
      ? "grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-x-4 gap-y-3 text-xs text-slate-700"
      : "space-y-3 text-xs text-slate-700 max-w-md";

  return (
    <div className={containerClass}>
      {fields.map((f) => (
        <div key={f.key}>
          <label className="block">
            <span className="block mb-1 font-medium">{f.label}</span>
            <input
              name={f.key}
              type={f.type || "text"}
              min={f.min}
              max={f.max}
              step={f.step}
              className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
              value={draft[f.key] ?? ""}
              onChange={(e) => {
                const { value } = e.target;
                setDraft((prev) => {
                  const next = { ...prev, [f.key]: value };
                  if (draftRef) draftRef.current = next;
                  return next;
                });
                setFieldErrors((prev) => ({ ...prev, [f.key]: null }));
              }}
              onBlur={() => {
                if (autoSave) void commitField(f);
              }}
            />
            {fieldErrors[f.key] && (
              <p className="mt-1 text-[11px] text-rose-600">{fieldErrors[f.key]}</p>
            )}
          </label>
        </div>
      ))}
      {layout === "grid" ? (
        <p className="sm:col-span-2 xl:col-span-3 text-[11px] text-slate-500">
          {autoSave
            ? "Changes save automatically when you leave a field."
            : "Click Apply and Save to store these values for every device."}
        </p>
      ) : (
        <p className="text-[11px] text-slate-500">
          {autoSave
            ? "Changes save automatically when you leave a field."
            : "Click Apply and Save to store these values for every device."}
        </p>
      )}
    </div>
  );
}

function NeonOperationalSettingsBlock({ settings, setSettings, fields }) {
  const [neonSettings, setNeonSettings] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);
  const [draftSettings, setDraftSettings] = React.useState(settings);
  const flatDraftRef = React.useRef({});
  const settingsRef = React.useRef(settings);
  settingsRef.current = settings;

  React.useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const data = await fetchFacilitySettings();
        const cs = data.calendar_settings || {};
        if (cs.version >= 1 && !cancelled) {
          setNeonSettings(cs);
          const mapped = calendarSettingsToLocal(cs);
          setDraftSettings((prev) => ({ ...prev, ...mapped }));
          setSettings((prev) => ({ ...prev, ...mapped }));
        }
      } catch (err) {
        if (!cancelled) toast.error(err.message || "Could not load settings");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [setSettings]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    const liveDraft = collectLiveDraft(event.currentTarget, fields, flatDraftRef.current);
    const committed = commitAllFields(
      { ...settingsRef.current, ...draftSettings },
      liveDraft,
      fields
    );
    const promoError = validateRentalPromo(committed.rentalPromo);
    if (promoError) { toast.error(promoError); return; }
    setDraftSettings(committed);
    setSaving(true);
    try {
      const payload = localToCalendarSettings(committed, neonSettings || {});
      const data = await saveFacilitySettings(payload);
      const saved = data.calendar_settings || payload;
      setNeonSettings(saved);
      const mapped = calendarSettingsToLocal(saved);
      setDraftSettings((prev) => ({ ...prev, ...mapped }));
      setSettings((prev) => ({ ...prev, ...mapped }));
      toast.success("Settings saved");
    } catch (err) {
      toast.error(err.message || "Could not save settings");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <p className="text-xs text-slate-500">Loading settings…</p>;
  }

  if (!neonSettings?.version) {
    return (
      <form onSubmit={handleSubmit}>
        <ProtectedSettingsBlock
          layout="grid"
          settings={settings}
          setSettings={setSettings}
          fields={fields}
          autoSave
          draftRef={flatDraftRef}
        />
        <div className="mt-4 flex items-center gap-3">
          <button
            type="submit"
            disabled={saving}
            className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
          >
            {saving ? "Saving…" : "Apply and Save"}
          </button>
          <span className="text-[11px] text-slate-500">
            These values are still local to this device. Apply and save them to share them with every device.
          </span>
        </div>
      </form>
    );
  }

  return (
    <form onSubmit={handleSubmit}>
      <ProtectedSettingsBlock
        layout="grid"
        settings={draftSettings}
        setSettings={setDraftSettings}
        fields={fields}
        autoSave={false}
        draftRef={flatDraftRef}
      />
      <fieldset className="mt-4 rounded-lg border border-slate-200 p-3 space-y-3 text-xs">
        <legend className="px-1 font-semibold">Temporary court rental promo</legend>
        <p>Mon–Thu, 8 a.m.–5 p.m. · 1 hour ₱400 · 2 hours ₱600 · 3 hours ₱1,000 · 4 hours ₱1,200. Uses total eligible court-hours across all courts in one booking. Two courts × 1 hour = ₱600; two courts × 2 hours = ₱1,200.</p>
        <label className="flex items-center gap-2"><input type="checkbox" checked={!!draftSettings.rentalPromo?.enabled}
          onChange={e => setDraftSettings(prev => ({ ...prev, rentalPromo: { ...resolveRentalPromo(prev.rentalPromo), enabled: e.target.checked } }))} />Enable promo</label>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {[['startDate', 'Start date'], ['endDate', 'End date']].map(([key, label]) => <label key={key}>{label}
            <input type="date" className="mt-1 block w-full rounded border border-slate-200 p-2" value={resolveRentalPromo(draftSettings.rentalPromo)[key] || ''}
              onChange={e => setDraftSettings(prev => ({ ...prev, rentalPromo: { ...resolveRentalPromo(prev.rentalPromo), [key]: e.target.value || null } }))} /></label>)}
        </div>
        <label className="block">Bookings crossing 5 p.m.
          <select className="mt-1 block w-full rounded border border-slate-200 p-2" value={resolveRentalPromo(draftSettings.rentalPromo).application}
            onChange={e => setDraftSettings(prev => ({ ...prev, rentalPromo: { ...resolveRentalPromo(prev.rentalPromo), application: e.target.value } }))}>
            <option value="eligible-hours">Promo for eligible hours; remaining hours at normal rates</option>
            <option value="whole-period">Entire continuous period must be inside the promo window</option>
          </select>
        </label>
        <p className="text-slate-500">Status: {rentalPromoStatus(draftSettings.rentalPromo)}. Dates use Asia/Manila. Existing saved bookings keep their prices.</p>
      </fieldset>
      <div className="mt-4 flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Public website pricing and hours use these values.
        </span>
      </div>
    </form>
  );
}

function NeonLockPinBlock() {
  const [oldPin, setOldPin] = React.useState("");
  const [newPin, setNewPin] = React.useState("");
  const [confirmPin, setConfirmPin] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState("");

  const handleSave = async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const current = String(form.elements.namedItem("oldPin")?.value ?? oldPin).replace(/\D/g, "");
    const next = String(form.elements.namedItem("newPin")?.value ?? newPin).replace(/\D/g, "");
    const confirmValue = String(
      form.elements.namedItem("confirmPin")?.value ?? confirmPin
    ).replace(/\D/g, "");
    setError("");
    if (!current) {
      setError("Enter the current PIN.");
      return;
    }
    if (!/^\d{6}$/.test(next)) {
      setError("New PIN must be 6 digits.");
      return;
    }
    if (next !== confirmValue) {
      setError("New PIN and confirmation do not match.");
      return;
    }
    setSaving(true);
    try {
      await changeLockPin({
        oldPin: current,
        newPin: next,
        confirmPin: confirmValue,
      });
      setOldPin("");
      setNewPin("");
      setConfirmPin("");
      toast.success("PIN saved");
    } catch (err) {
      setError(err.message || "Could not save PIN");
      toast.error(err.message || "Could not save PIN");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSave} className="space-y-3 text-xs text-slate-700 max-w-md">
      <label className="block">
        <span className="block mb-1 font-medium">Current PIN</span>
        <input
          name="oldPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={oldPin}
          onChange={(e) => setOldPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">New PIN</span>
        <input
          name="newPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={newPin}
          onChange={(e) => setNewPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">Confirm new PIN</span>
        <input
          name="confirmPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={confirmPin}
          onChange={(e) => setConfirmPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      {error && <p className="text-[11px] text-rose-600">{error}</p>}
      <div className="flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {saving ? "Saving…" : "Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          This PIN is required after every refresh or reload. It is stored online, not in this browser.
        </span>
      </div>
    </form>
  );
}

function NeonAdminPasswordBlock() {
  const [oldPassword, setOldPassword] = React.useState("");
  const [newPassword, setNewPassword] = React.useState("");
  const [confirmPassword, setConfirmPassword] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState("");

  const handleSave = async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const current = String(form.elements.namedItem("oldPassword")?.value ?? oldPassword);
    const next = String(form.elements.namedItem("newPassword")?.value ?? newPassword);
    const confirmValue = String(
      form.elements.namedItem("confirmPassword")?.value ?? confirmPassword
    );
    setError("");
    if (!current) {
      setError("Enter the current password.");
      return;
    }
    if (!next || next.length < 4) {
      setError("New password must be at least 4 characters.");
      return;
    }
    if (next !== confirmValue) {
      setError("New password and confirmation do not match.");
      return;
    }
    setSaving(true);
    try {
      await changeAdminPassword({
        oldPassword: current,
        newPassword: next,
        confirmPassword: confirmValue,
      });
      setOldPassword("");
      setNewPassword("");
      setConfirmPassword("");
      toast.success("Password saved");
    } catch (err) {
      setError(err.message || "Could not save password");
      toast.error(err.message || "Could not save password");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSave} className="space-y-3 text-xs text-slate-700 max-w-md">
      <label className="block">
        <span className="block mb-1 font-medium">Current password</span>
        <input
          name="oldPassword"
          type="password"
          autoComplete="current-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={oldPassword}
          onChange={(e) => setOldPassword(e.target.value)}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">New password</span>
        <input
          name="newPassword"
          type="password"
          autoComplete="new-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">Confirm new password</span>
        <input
          name="confirmPassword"
          type="password"
          autoComplete="new-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
        />
      </label>
      {error && <p className="text-[11px] text-rose-600">{error}</p>}
      <div className="flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Login checks this password on the server, not the copy in this browser.
        </span>
      </div>
    </form>
  );
}

