export function mapQueueTeamMetaToMatchSides(teamMeta) {
  if (
    !teamMeta ||
    !Array.isArray(teamMeta?.sideA?.players) ||
    !Array.isArray(teamMeta?.sideB?.players)
  ) {
    return null;
  }
  return {
    green: [...teamMeta.sideA.players],
    blue: [...teamMeta.sideB.players],
  };
}

export function resolveMatchSidesForDisplay(match) {
  const fallbackGreenPlayers = Array.isArray(match?.teams?.green) ? match.teams.green : [];
  const fallbackBluePlayers = Array.isArray(match?.teams?.blue) ? match.teams.blue : [];
  const sideA = match?.teamMeta?.sideA;
  const sideB = match?.teamMeta?.sideB;

  return {
    green: {
      teamId: sideA?.teamId ?? null,
      name: sideA?.name || "Green",
      color: sideA?.color || "#22C55E",
      letter: sideA?.letter || "G",
      players: Array.isArray(sideA?.players) ? sideA.players : fallbackGreenPlayers,
    },
    blue: {
      teamId: sideB?.teamId ?? null,
      name: sideB?.name || "Blue",
      color: sideB?.color || "#60A5FA",
      letter: sideB?.letter || "B",
      players: Array.isArray(sideB?.players) ? sideB.players : fallbackBluePlayers,
    },
  };
}
