/**
 * Format booking audit/change logs for History UI and CSV export.
 * Supports both calendar audit shape ({ timestamp, action, details, adminId })
 * and website review shape ({ at, action, notes, reviewedBy }).
 */

export function formatHistoryLogTime(log) {
  const raw = log?.timestamp || log?.at;
  if (!raw) return "";
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString("en-PH", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

export function formatHistoryLogActor(log) {
  return (log?.adminId || log?.reviewedBy || "").trim();
}

export function formatHistoryLogNotes(log) {
  return (log?.details || log?.notes || "").trim();
}

export function formatHistoryLogAction(log) {
  const action = String(log?.action || "").trim();
  if (!action) return "";
  return action.replace(/_/g, " ");
}

/** Single human-readable line for one audit entry. */
export function formatHistoryLogLine(log) {
  if (!log) return "";
  const action = formatHistoryLogAction(log);
  const actor = formatHistoryLogActor(log);
  const when = formatHistoryLogTime(log);
  const notes = formatHistoryLogNotes(log);
  const parts = [action];
  if (actor) parts.push(`by ${actor}`);
  if (when) parts.push(`at ${when}`);
  let line = parts.filter(Boolean).join(" · ");
  if (notes) line = `${line}: ${notes}`;
  return line;
}

/** Newest-first lines for UI. */
export function formatHistoryLogLines(logs) {
  if (!Array.isArray(logs) || !logs.length) return [];
  return logs
    .slice()
    .reverse()
    .map(formatHistoryLogLine)
    .filter(Boolean);
}

/** Pipe-joined string for CSV cells. */
export function formatHistoryLogsForCsv(logs) {
  return formatHistoryLogLines(logs).join(" | ");
}

/** Booking (created) date as YYYY-MM-DD local when possible. */
export function formatBookingCreatedDate(createdAt) {
  if (!createdAt) return "";
  const d = new Date(createdAt);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-CA");
}

export function formatBookingCreatedDateTime(createdAt) {
  if (!createdAt) return "";
  const d = new Date(createdAt);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString("en-PH", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

/** Parse createdAt to epoch ms; invalid/missing → null. */
function createdAtMs(createdAt) {
  if (!createdAt) return null;
  const t = new Date(createdAt).getTime();
  return Number.isFinite(t) ? t : null;
}

/**
 * Sort comparator: newest booked (createdAt) first.
 * Missing/invalid createdAt go last; ties break by id ascending.
 */
export function compareBookingsByCreatedAtDesc(a, b) {
  const aMs = createdAtMs(a?.createdAt);
  const bMs = createdAtMs(b?.createdAt);

  if (aMs != null && bMs != null) {
    if (bMs !== aMs) return bMs - aMs;
  } else if (aMs != null) {
    return -1;
  } else if (bMs != null) {
    return 1;
  }

  const aId = String(a?.id ?? "");
  const bId = String(b?.id ?? "");
  return aId.localeCompare(bId);
}

/** Return a new array sorted by createdAt descending (newest booking first). */
export function sortBookingsByCreatedAtDesc(bookings) {
  if (!Array.isArray(bookings)) return [];
  return bookings.slice().sort(compareBookingsByCreatedAtDesc);
}
